def sim(config, data):
    dt = 0.1
    acc = AdaptiveCruiseControl(config)
    ego_speed = 0.0
    distance = None
    lead_present = False
    set_speed = 30.0

    rise_time = None
    max_cruise = 0.0
    cruise_final = []
    # Collect follow errors excluding emergency recovery
    follow_errors_stable = []
    min_dist = float('inf')

    for sensor in data:
        t = sensor['time']
        lead_speed = sensor['lead_speed']
        if lead_speed is not None:
            if not lead_present:
                distance = sensor['distance']
                lead_present = True
        else:
