            lead_present = False

        accel, mode, dist_error = acc.compute(ego_speed, lead_speed, distance, dt)

        if rise_time is None and ego_speed >= 27:
            rise_time = t
        if mode == 'cruise':
            if ego_speed > max_cruise: max_cruise = ego_speed
            if t >= 140: cruise_final.append(ego_speed)
